function base(
  name: string,
  parentId: string | null,
  stage: number,
  units: number,
): ComponentDeployment {
  return {
    deploymentId: name,
    slug: name,
    displayName: name,
    type: 'Base',
    targets: [],
    parentDeploymentId: parentId,
    stage,
    upgradeableCount: 0,
    unappliedCount: 0,
    unitCount: units,
    liveStatusProvider: 'unknown',
    labels: parentId === null ? {} : { Environment: name, Stage: name },
    configSignals: { staleUnits: 0, unreleasedUnits: 0, gatedUnits: 0 },
  };
}

function deployment(row: Row): ComponentDeployment {
  const [name, env, region, department, stale, unreleased, gated, sync, health, units] = row;
  return {
    deploymentId: name,
    slug: name,
    displayName: name,
    type: 'Deployment',
    targets: [{ targetId: `target-${name}`, name, label: name }],
    parentDeploymentId: env,
    stage: 2,
    upgradeableCount: stale,
    unappliedCount: unreleased + gated,
    unitCount: units,
    liveStatus: { source: 'argobot', syncStatus: sync, healthStatus: health },
    liveStatusProvider: 'argocd',
    labels: {
      Region: region,
      ...(department ? { Department: department } : {}),
      Environment: env,
      Stage: env,
      Cluster: name,
      Variant: name,
    },
    configSignals: { staleUnits: stale, unreleasedUnits: unreleased, gatedUnits: gated },
  };
}

/** The nodes of one Meridian Component, Bases first, then Deployments in slug order. */
export function meridianComponent(name: MeridianComponentName): ComponentDeployment[] {
  const rows = RAW[name];
  const envs = ENV_ORDER.filter((env) => rows.some((r) => r[1] === env));
  // Every Space of a Meridian Component holds the same Units.
  const units = rows[0][9];
  return [
    base(ROOT_ID, null, 0, units),
    ...envs.map((env) => base(env, ROOT_ID, 1, units)),
    ...rows.map(deployment).sort((a, b) => a.slug.localeCompare(b.slug)),
  ];
}
